def google_rss(query):
    """구글 뉴스 검색 RSS 주소 (최근 7일 한정)"""
    q = urllib.parse.quote(query + " when:7d")
    return f"https://news.google.com/rss/search?q={q}&hl=ko&gl=KR&ceid=KR:ko"


