def google_rss_en(query):
    q = urllib.parse.quote(query + " when:2d")
    return f"https://news.google.com/rss/search?q={q}&hl=en-US&gl=US&ceid=US:en"


def translate_ko(text):
    """영문 → 한글 번역 (구글 번역의 공개 주소 사용. 실패하면 None)"""
    try:
        url = ("https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=ko&dt=t&q="
               + urllib.parse.quote(text))
        req = urllib.request.Request(url, headers={"User-Agent": UA})
        with urllib.request.urlopen(req, timeout=10) as r:
            data = json.loads(r.read().decode("utf-8", "ignore"))
        out = "".join(seg[0] for seg in data[0] if seg and seg[0]).strip()
        return out or None
    except Exception:
        return None


def build_feed_list():
    feeds = []
    for name, url in PRESS_FEEDS:
        feeds.append({"name": name, "url": url, "kind": "press", "hint": None})
    for q in TOPIC_QUERIES:
        feeds.append({"name": "구글 뉴스", "url": google_rss(q), "kind": "google", "hint": None})
    for city, sido in REGION_QUERIES:
        feeds.append({"name": "구글 뉴스", "url": google_rss(REGION_QUERY_TEMPLATE.format(city)),
                      "kind": "google", "hint": sido})
    return feeds


