def classify_en(title):
    """해외 언론 영문 제목 → 소분류. 실제 사건이 아니면 None."""
    if not (EN_EVENT_RE.search(title) and EN_PLACE_RE.search(title)):
        return None
    if re.search(r"football|soccer|\bmatch\b|league|\bgoal\b|tournament|world cup|olympic|\bscore|film|movie|review|book|novel|game\b", title, re.I):
        return None                      # 스포츠·문화 기사
    if EN_TALK_RE.search(title) and not EN_HARD_RE.search(title):
        return None                      # 경고·전망·분석 등은 제외
    if re.search(r"North Korea|Pyongyang", title, re.I):
        return "국가 안보"
    if re.search(r"sunk|sinks|sinking|warship|vessel|\bship\b|tanker|navy|Red Sea|Black Sea|Hormuz|seiz|torpedo|hijack", title, re.I):
        return "해상·격침"
    if re.search(r"gunmen|terror|suicide bomb|assassinat|shooting|hostage|ambush", title, re.I):
        return "테러·피격"
    if re.search(r"air\s?strike|air raid|missile|drone|bomb|shell|rocket|strike|struck|shot down|downed|intercept", title, re.I):
        return "공습·타격"
    return "전쟁·교전"


