# 사설·분석형 제목
EDITORIAL_RE = re.compile(r"\?\s*$|할까|일까|하나\?|해법|과제|진단|쟁점|필요하다|바람직|시급|되짚어|돌아보니|살펴보니|따져보니|이유는|까닭|속사정|명과\s*암|빛과\s*그림자")


def is_not_incident(title, content):
    """사건사고 '발생' 기사가 아닌 것(서평·광고·정책·발언·사설)을 걸러냄"""
    if NON_NEWS_RE.search(title):
        return True
    text = title + " " + (content or "")
    if REVIEW_RE.search(title) or (REVIEW_RE.search(text) and re.search(r"지음|옮김|\d+쪽|출판사|펴냄", text)):
        return True
    if AD_RE.search(text):
        return True
    fact = FACT2_RE.search(title)
    if not fact:
        if POLICY_RE.search(title):
            return True
        if SPEAKER_RE.search(title) and QUOTE_RE.search(title):
            return True                  # 누가 "…"라고 말했다는 기사
        if EDITORIAL_RE.search(title):
            return True
    elif SPEAKER_RE.search(title) and QUOTE_RE.search(title) and POLICY_RE.search(title):
        return True                      # 사건 낱말이 있어도 '○○의원 "…해야"' 꼴이면 발언 기사
    return False


# 사건사고가 아닌 홍보·캠페인·모음 기사
CAMPAIGN_RE = re.compile(r"캠페인|홍보|협약|설명회|공모전|서포터즈|간담회|세미나|발대식|시상식|기념식|합동\s*훈련|모의\s*훈련|안전\s*점검\s*실시|대책\s*회의|브리핑|운세|오늘의\s*뉴스|주요\s*뉴스|뉴스\s*모음|헤드라인|포토\s*뉴스|개최|예방(?!\s*접종)")
INCIDENT_FACT_RE = re.compile(r"사망|숨져|숨졌|검거|구속|입건|체포|부상|피해자|발생|발견|적발|붙잡")
FINANCE_RE = re.compile(r"주가|증시|코스피|코스닥|나스닥|환율|금리|비트코인|이더리움|시황|목표주가|상장|배당|펀드|매수|매도|실적")
ENT_SPORT_RE = re.compile(r"열애|결혼|이혼|스캔들|아이돌|드라마|영화|앨범|콘서트|시청률|리그|토너먼트|골프")
POLITICS_RE = re.compile(r"대통령|국회|의원|장관|정당|여당|야당|민주당|국민의힘|특검|청문회|탄핵|선거|국정감사|총리|비대위|시장|군수|구청장|도지사|공천|당원")
METAPHOR_RE = re.compile(r"논란|갈등|파문|후폭풍|반발|공방|파장|감찰|집단행동|비판|압박|이해\s*충돌|국감|의혹")
AMBIGUOUS_SUBS = {"화재·폭발", "붕괴·산업재해", "교통사고", "구조·안전사고", "자연재해"}   # 비유로도 쓰이는 낱말(폭발·붕괴·충돌...)
PRE_CLEAN = re.compile(r"사기\s*진작|사기\s*저하|사기업|사기\s*충천")


def classify(title, content):
    """(소분류, 대분류) 반환. 사건사고가 아니면 None."""
    if CAMPAIGN_RE.search(title) and not INCIDENT_FACT_RE.search(title):
        return None
    t = PRE_CLEAN.sub(" ", title)
    full = PRE_CLEAN.sub(" ", title + " " + (content or ""))
    if NON_NEWS_RE.search(title) or AD_RE.search(full):
        return None

    # 해외 분쟁 / 국가 안보 : 실제 벌어진 사건만 (경고·전망·분석은 제외)
    zone = FOREIGN_RE.search(t) or (BIG_COUNTRY_RE.search(t) and MIL_RE.search(t))
    if zone and CONFLICT_RE.search(t) and not SPORTS_RE.search(t):
        if KO_TALK_RE.search(t) and not KO_CASUALTY_RE.search(t):
            return None
        if REVIEW_RE.search(t):
            return None
        return overseas_sub(t), "해외·안보"
    if NK_RE.search(t) and NK_EVENT_RE.search(t):
        if KO_TALK_RE.search(t) and not KO_CASUALTY_RE.search(t) and not re.search(r"발사|침투|침범|귀순|월북", t):
            return None
        return "국가 안보", "해외·안보"

    if is_not_incident(title, content):
        return None

    found = None
    for sub, group, rx, broad in RULES:          # 1차: 제목만
        if rx.search(t):
            found = (sub, group, broad); break
    if not found:
        for sub, group, rx, broad in RULES:      # 2차: 제목+요약 (넓은 분류는 제외)
            if broad:
                continue
            if rx.search(full):
                found = (sub, group, broad); break
    if not found:
        return None

    sub, group, broad = found
    if sub == "구조·안전사고" and re.search(r"고양이|강아지|반려|동물|새끼", t):
        return None
    if FINANCE_RE.search(t) and sub not in ("사기·보이스피싱", "금융·횡령·도박", "공직자 비리"):
        return None
    if ENT_SPORT_RE.search(t) and group in ("재난·사고", "실종·제보"):
        return None
    # 스포츠 기사: 골 '폭발', 순위 '추락' 같은 표현 때문에 잘못 잡히는 것 방지
    if SPORTS_RE.search(t) and (sub in AMBIGUOUS_SUBS or broad or group in ("재난·사고", "실종·제보")) and not FACT2_RE.search(t):
        return None
    if QUOTED_METAPHOR_RE.search(t) and sub in AMBIGUOUS_SUBS and not FACT2_RE.search(t):
        return None
    if sub == "기타 범죄" and broad and (POLITICS_RE.search(t) or FINANCE_RE.search(t)):
        return None
    if sub in AMBIGUOUS_SUBS and (METAPHOR_RE.search(t) or POLITICS_RE.search(t)) and not INCIDENT_FACT_RE.search(t):
        return None
    return sub, group


