def _rx(alias):
    body = r"\s*".join(re.escape(p) for p in alias.split(" "))
    return re.compile(r"(?<![가-힣])" + body + r"(?:(?![가-힣])|(?=[" + _SUFFIX_OK + r"]))")


@functools.lru_cache(maxsize=None)
def _dong_rx(label):
    return _rx(label)


class Region:
    def __init__(self, sido, name, lat, lng):
        self.sido, self.name, self.lat, self.lng = sido, name, lat, lng
        self.label = f"{sido} {name}"
        self.strong, self.weak = set(), set()
        self.dongs = None

    @property
    def radius(self):
        if self.name.endswith("구"):
            return 0.008
        if self.name.endswith("시"):
            return 0.02
        return 0.03


def build_regions():
    rows = []
    for sido, entries in SIGUNGU.items():
        for name, lat, lng in entries:
            r = Region(sido, name, lat, lng)
            parts = name.split(" ")
            if sido == "경기도" and name == "광주시":
                r.strong |= {"경기 광주", "경기도 광주", "경기 광주시", "경기도 광주시"}
            elif len(parts) == 2:                      # 예: 수원시 영통구
                city, gu = parts
                r.strong |= {name, gu, f"{city[:-1]} {gu}"}
            else:
                r.strong.add(name)
                stem = name[:-1]
                if name == "세종시":
                    r.strong.add("세종특별자치시")
                elif name.endswith("구") and len(stem) >= 2:
                    (r.strong if stem in _STANDALONE_GU else r.weak).add(stem)   # 그 외 줄임말은 시·도가 같이 있을 때만
                elif name.endswith("시") and stem not in SIDO_RX_NAMES:
                    (r.weak if stem in _NEED_SUFFIX else r.strong).add(stem)
                elif name.endswith("군"):
                    r.weak.add(stem)
            for sub, marks in LANDMARKS.items():
                if sub == r.label:
                    r.strong |= set(marks)
            r.inst = set()
            for table in (INSTITUTIONS, INSTITUTIONS_NATIONAL):
                for sub, marks in table.items():
                    if sub.strip() == r.label:
                        r.inst |= set(marks)
            d = DONG_DATA.get(r.label)
            if d:
                r.dongs = _dong_aliases(d)
            rows.append(r)
    # 같은 표현이 여러 지역에 있으면(예: 중구, 동구, 서구) 시·도가 함께 있어야만 인정
    count = {}
    for r in rows:
        for a in r.strong | r.weak:
            count[a] = count.get(a, 0) + 1
    for r in rows:
        r.compiled = []
        for a in r.strong:
            r.compiled.append((_rx(a), a, count[a] > 1, a.split(" ")[0]))
        for a in r.weak:
            r.compiled.append((_rx(a), a, True, a.split(" ")[0]))
        # 기관명은 글자 그대로 포함되어 있는지만 확인 (후순위)
        r.inst_compiled = [(re.compile(a), a) for a in r.inst]
    return rows


SIDO_RX_NAMES = {"서울", "부산", "대구", "인천", "광주", "대전", "울산", "세종", "제주"}


def _dong_aliases(csv):
    out = []
    seen = set()
    for d in csv.split(","):
        d = d.strip()
        if not d or d == "전체" or "가동" in d:
            continue
        m = re.match(r"^([가-힣]+?)(\d|제)", d)
        label = (m.group(1) + d[-1]) if m else d
        if len(label) < 3 or label in seen:
            continue
        seen.add(label)
        out.append(label)
    return out


_REGIONS = None


def regions():
    global _REGIONS
    if _REGIONS is None:
        _REGIONS = build_regions()
    return _REGIONS


def find_sidos(text):
    t = re.sub(r"경기도?\s*광주", "경기 ", text)       # '경기 광주'가 광주광역시로 오해되지 않도록
    return {s: m.start() for s, rx in SIDO_RX.items() for m in [rx.search(t)] if m}


def match_sigungu(text, hint_sido):
    text = _NOT_PLACE.sub(" ", text)
    sidos = set(find_sidos(text))
    if hint_sido:
        sidos.add(hint_sido)
    best = None
    for r in regions():
        for rx, alias, need_sido, probe in r.compiled:
            if probe not in text:                      # 빠른 사전 검사 (속도 향상)
                continue
            if need_sido and r.sido not in sidos:
                continue
            m = rx.search(text)
            if not m:
                continue
            key = (0, m.start(), -len(alias))
            if best is None or key < best[0]:
                best = (key, r)
        for rx, alias in r.inst_compiled:              # 법원·검찰·부처·공공기관 등 기관 소재지 (후순위)
            m = rx.search(text)
            if not m:
                continue
            key = (1, m.start(), -len(m.group()))
            if best is None or key < best[0]:
                best = (key, r, m.group())
    if not best:
        return None
    r = best[1]
    label = r.label
    if r.dongs:
        dbest = None
        for dlabel in r.dongs:
            if dlabel[:2] not in text:
                continue
            m = _dong_rx(dlabel).search(text)
            if m and (dbest is None or m.start() < dbest[0]):
                dbest = (m.start(), dlabel)
        if dbest:
            label += " " + dbest[1]
    inst_alias = best[2] if len(best) > 2 else None
    return label, r.lat, r.lng, r.radius, inst_alias


def _jitter(key, radius):
    h = hashlib.md5(key.encode("utf-8")).digest()
    return (h[0] / 255 - 0.5) * 2 * radius, (h[1] / 255 - 0.5) * 2 * radius


def locate(title, content, hint_sido=None, group=None):
    """(위치이름, 위도, 경도) 반환. 모르면 (미상, None, None)"""
    key = title
    full = title + " | " + (content or "")[:300]
    if group == "해외·안보":
        for label, la, ln, words in FOREIGN_PLACES:
            if any(w in full for w in words):
                dy, dx = _jitter(key, 0.25)
                if label == "북한":
                    return "북한·접경지역", round(la + dy, 4), round(ln + dx, 4)
                return f"해외 ({label})", round(la + dy, 4), round(ln + dx, 4)
        return "해외 (위치 미상)", None, None
    for scope in (title, full):
        res = match_sigungu(scope, hint_sido)
        if res:
            label, lat, lng, rad, inst_alias = res
            if inst_alias:
                # 기관명으로만 찾은 경우: 기사에 다른 시·도가 따로 적혀 있으면 그쪽을 우선
                other = find_sidos(scope.replace(inst_alias, " "))
                if other:
                    sido = min(other, key=other.get)
                    la, ln = SIDO_CENTER[sido]
                    dy, dx = _jitter(key, 0.10)
                    return sido, round(la + dy, 4), round(ln + dx, 4)
            dy, dx = _jitter(key, rad)
            return label, round(lat + dy, 4), round(lng + dx, 4)
    for scope in (title, full):
        s = find_sidos(scope)
        if s:
            sido = min(s, key=s.get)
            la, ln = SIDO_CENTER[sido]
            dy, dx = _jitter(key, 0.10)
            return sido, round(la + dy, 4), round(ln + dx, 4)
    if hint_sido:
        la, ln = SIDO_CENTER[hint_sido]
        dy, dx = _jitter(key, 0.10)
        return hint_sido, round(la + dy, 4), round(ln + dx, 4)
    return "대한민국 (세부 위치 미상)", None, None


# ───────────────────────────────────────────────────────────────
# 4. 수집 보조 함수
# ───────────────────────────────────────────────────────────────
class _HTMLFilter(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts = []

    def handle_data(self, d):
        self.parts.append(d)


def clean_text(s):
    if not s:
        return ""
    f = _HTMLFilter()
    try:
        f.feed(s)
        s = "".join(f.parts)
    except Exception:
        pass
    return re.sub(r"\s+", " ", s).strip()


def split_publisher(title):
    """'기사 제목 - 언론사' → ('기사 제목', '언론사')"""
    m = re.match(r"^(.*\S)\s+[-–|]\s+([^-–|]{2,20})$", title)
    if m:
        return m.group(1).strip(), m.group(2).strip()
    return title, None


def norm_key(title):
    return re.sub(r"[^0-9A-Za-z가-힣]", "", title)[:60]


def make_id(key):
    return int(hashlib.md5(key.encode("utf-8")).hexdigest()[:12], 16)


WEEKDAYS_KR = ["월요일", "화요일", "수요일", "목요일", "금요일", "토요일", "일요일"]


def fmt_time(ts):
    dt = datetime.fromtimestamp(ts, KST)
    return f"{dt.strftime('%Y.%m.%d')} ({WEEKDAYS_KR[dt.weekday()]}) {dt.strftime('%H:%M')}"


def fetch_entries(url):
    last = None
    for _ in range(2):
        try:
            req = urllib.request.Request(url, headers={
                "User-Agent": UA, "Accept": "application/rss+xml, application/xml, text/xml, */*"})
            with urllib.request.urlopen(req, timeout=12) as r:
                data = r.read()
            return feedparser.parse(data).entries
        except Exception as e:      # noqa
            last = e
            time.sleep(1.5)
    raise last


def entry_timestamp(entry):
    for k in ("published_parsed", "updated_parsed"):
        v = entry.get(k)
        if v:
            try:
                return float(calendar.timegm(v))
            except Exception:
                pass
    return None


OVERSEAS_RE = re.compile(r"케냐|미국|중국|일본|인도네시아|인도|베트남|태국|필리핀|캄보디아|유럽|영국|프랑스|독일|이탈리아|브라질|멕시코|캐나다|호주|튀르키예|이집트|나이지리아|파키스탄|방글라데시|네팔|대만|홍콩|아프리카|중동|러시아|우크라이나")
KOREAN_LINK_RE = re.compile(r"한국인|국민|교민|우리\s*국민|한국")


def is_overseas_noise(title, group, lat):
    """한국과 무관한 해외 사고 기사 (위치를 못 찾았고 해외 지명이 있을 때)"""
    return (lat is None and group in ("재난·사고", "교통사고", "실종·제보", "강력범죄", "공직·기타")
            and OVERSEAS_RE.search(title) and not KOREAN_LINK_RE.search(title))


def build_item(entry, feed, now_ts):
    title_raw = clean_text(entry.get("title", ""))
    if not title_raw:
        return None
    link = entry.get("link", "") or ""
    ts = entry_timestamp(entry)
    if ts is None:
        ts = now_ts
    ts = min(ts, now_ts)

    source = feed["name"]
    title = title_raw
    if feed["kind"] == "google":
        title, pub = split_publisher(title_raw)
        src = entry.get("source")
        if isinstance(src, dict) and src.get("title"):
            pub = clean_text(src.get("title"))
            if title_raw.endswith(" - " + pub):
                title = title_raw[: -len(" - " + pub)].strip()
        if pub:
            source = pub
        content = title
    else:
        content = clean_text(entry.get("summary") or entry.get("description") or "") or title
    content = content[:400]

    cls = classify(title, content)
    if not cls:
        return None
    sub, group = cls
    item = make_item(title, content, sub, group, source, link, ts, feed.get("hint"))
    return None if is_overseas_noise(title, group, item["lat"]) else item


def make_item(title, content, sub, group, source, link, ts, hint, orig=None):
    loc, lat, lng = locate(title, content + (" " + orig if orig else ""), hint, group)
    summary = content[:130] + ("..." if len(content) > 130 else "")
    return {
        "id": make_id(norm_key(title)),
        "title": title,
        "summary": summary,
        "content": content,
        "category": sub,
        "group": group,
        "location": loc,
        "lat": lat,
        "lng": lng,
        "time": fmt_time(ts),
        "source": source,
        "link": link,
        "timestamp": ts,
        "hint": hint,
        "orig": orig,       # 해외 언론 기사의 원문(영문) 제목
    }


# ── 구글 뉴스 링크를 실제 언론사 기사 주소로 바꾸기 (실패해도 괜찮습니다) ──
def _b64_legacy(art_id):
    try:
        b = base64.urlsafe_b64decode(art_id + "=" * (-len(art_id) % 4)).decode("latin1")
        if b.startswith("\x08\x13\x22"):
            b = b[3:]
        if b.endswith("\xd2\x01\x00"):
            b = b[:-3]
        ba = bytearray(b, "latin1")
        n = ba[0]
        s = b[2:n + 1] if n >= 0x80 else b[1:n + 1]
        return s if s.startswith("http") else None
    except Exception:
        return None


def resolve_google_link(link):
    m = re.search(r"/articles/([^/?]+)", link)
    if not m:
        return None
    art_id = m.group(1)
    url = _b64_legacy(art_id)
    if url:
        return url
    try:
        req = urllib.request.Request(f"https://news.google.com/rss/articles/{art_id}", headers={"User-Agent": UA})
        html = urllib.request.urlopen(req, timeout=10).read().decode("utf-8", "ignore")
        sg = re.search(r'data-n-a-sg="([^"]+)"', html)
        ts = re.search(r'data-n-a-ts="([^"]+)"', html)
        if not (sg and ts):
            return None
        inner = ('["garturlreq",[["X","X",["X","X"],null,null,1,1,"US:en",null,1,null,null,null,null,null,0,1],'
                 '"X","X",1,[1,1,1],1,1,null,0,0,null,0],"%s",%s,"%s"]' % (art_id, ts.group(1), sg.group(1)))
        payload = "f.req=" + urllib.parse.quote(json.dumps([[["Fbv4je", inner]]]))
        req = urllib.request.Request(
            "https://news.google.com/_/DotsSplashUi/data/batchexecute", data=payload.encode("utf-8"),
            headers={"Content-Type": "application/x-www-form-urlencoded;charset=UTF-8", "User-Agent": UA})
        text = urllib.request.urlopen(req, timeout=10).read().decode("utf-8", "ignore")
        data = json.loads(text.split("\n\n")[1])
        real = json.loads(data[0][2])[1]
        return real if isinstance(real, str) and real.startswith("http") else None
    except Exception:
        return None


# ───────────────────────────────────────────────────────────────
# 5. 저장/불러오기 및 실행
# ───────────────────────────────────────────────────────────────
def load_existing():
    if not os.path.exists(NEWS_JSON):
        return []
    try:
        with open(NEWS_JSON, encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, list) else []
    except Exception as e:
        print(f"[경고] 기존 news.json 을 읽지 못했습니다: {e}")
        return []


def reprocess_existing(old):
    """기존 기사를 최신 분류/위치 규칙으로 다시 계산 (규칙을 고치면 과거 기사에도 적용됨)"""
    out = {}
    for it in old:
        try:
            title = it.get("title", "")
            source = it.get("source", "")
            if source.startswith("구글 뉴스"):
                t2, pub = split_publisher(title)
                if pub:
                    title, source = t2, pub
            if it.get("source") == "시민 직접 제보":
                continue
            content = it.get("content") or title
            ts = float(it.get("timestamp") or 0)
            if not ts:
                continue
            orig = it.get("orig")
            if orig:                                   # 해외 언론 번역 기사
                sub_en = classify_en(orig)
                if not sub_en:
                    continue
                out[norm_key(title)] = make_item(title, title, sub_en, "해외·안보", source, it.get("link", ""), ts, None, orig)
                continue
            cls = classify(title, content)
            if not cls:
                continue
            item = make_item(title, content[:400], cls[0], cls[1], source, it.get("link", ""), ts, it.get("hint"))
            if is_overseas_noise(title, cls[1], item["lat"]):
                continue
            out[norm_key(title)] = item
        except Exception:
            continue
    return out


def main():
    now = datetime.now(KST)
    now_ts = now.timestamp()
    cutoff_ts = (now - timedelta(days=KEEP_DAYS)).timestamp()
    print("=== 우리동네 사건사고 수집 시작 ===", now.strftime("%Y-%m-%d %H:%M:%S"))

    items = reprocess_existing(load_existing())
    print(f"기존 기사 {len(items)}건 불러옴")

    new_count = 0
    ok_feeds = fail_feeds = 0
    started = time.time()
    for feed in build_feed_list():
        if time.time() - started > 300:
            print("[주의] 수집 시간이 길어져 남은 국내 주소는 다음 실행으로 넘깁니다.")
            break
        label = f"{feed['name']}" + (f" [{feed['hint']}]" if feed["hint"] else "") + f" {feed['url'][:70]}"
        try:
            entries = fetch_entries(feed["url"])
        except Exception as e:
            fail_feeds += 1
            print(f"[실패] {label} → {type(e).__name__}: {str(e)[:80]}")
            continue
        got = 0
        for entry in entries[:300]:
            try:
                it = build_item(entry, feed, now_ts)
            except Exception:
                it = None
            if not it or it["timestamp"] < cutoff_ts:
                continue
            key = norm_key(it["title"])
            old = items.get(key)
            if old is None:
                items[key] = it
                new_count += 1
                got += 1
            else:
                # 같은 기사면, 구글 링크보다 언론사 직접 링크를 우선
                if old["link"].startswith("https://news.google.com") and not it["link"].startswith("https://news.google.com"):
                    old["link"] = it["link"]
        ok_feeds += 1
        print(f"[OK ] {label} → 전체 {len(entries)}건 중 신규 사건사고 {got}건")
        time.sleep(0.3)

    # ── 해외 언론: 실제 발생한 분쟁·공격 기사만 골라 한글로 번역 ──
    known_orig = {norm_key(v["orig"]) for v in items.values() if v.get("orig")}
    foreign = [{"name": n, "url": u, "google": False} for n, u in FOREIGN_FEEDS]
    foreign += [{"name": "해외 언론", "url": google_rss_en(q), "google": True} for q in FOREIGN_QUERIES]
    translated = 0
    for feed in foreign:
        if time.time() - started > 480:
            print("[주의] 수집 시간이 길어져 남은 해외 주소는 다음 실행으로 넘깁니다.")
            break
        label = f"{feed['name']} {feed['url'][:70]}"
        try:
            entries = fetch_entries(feed["url"])
        except Exception as e:
            fail_feeds += 1
            print(f"[실패] {label} → {type(e).__name__}: {str(e)[:80]}")
            continue
        ok_feeds += 1
        got = 0
        for entry in entries[:60]:
            if translated >= MAX_TRANSLATE_PER_RUN:
                break
            try:
                title_en = clean_text(entry.get("title", ""))
                source = feed["name"]
                if feed["google"]:
                    title_en, pub = split_publisher(title_en)
                    source = pub or source
                if not title_en or norm_key(title_en) in known_orig:
                    continue
                sub_en = classify_en(title_en)
                if not sub_en:
                    continue
                ts = min(entry_timestamp(entry) or now_ts, now_ts)
                if ts < cutoff_ts:
                    continue
                title_ko = translate_ko(title_en)
                translated += 1
                time.sleep(0.3)
                if not title_ko:
                    continue                       # 번역 실패 → 다음 실행 때 다시 시도
                known_orig.add(norm_key(title_en))
                it = make_item(title_ko, title_ko, sub_en, "해외·안보", source, entry.get("link", "") or "", ts, None, title_en)
                key = norm_key(title_ko)
                if key not in items:
                    items[key] = it
                    new_count += 1
                    got += 1
            except Exception:
                continue
        print(f"[OK ] {label} → 전체 {len(entries)}건 중 신규 해외 사건 {got}건")
        time.sleep(0.3)
    print(f"해외 기사 번역 시도: {translated}건")

    # 구글 뉴스 링크 → 원문 주소 (최신 기사부터 일부만)
    resolved = 0
    pending = sorted([v for v in items.values() if v["link"].startswith("https://news.google.com")],
                     key=lambda x: -x["timestamp"])
    for v in pending[:MAX_RESOLVE_PER_RUN]:
        real = resolve_google_link(v["link"])
        if real:
            v["link"] = real
            resolved += 1
        time.sleep(0.4)
    print(f"원문 주소로 변환: {resolved}건 (구글 링크 남은 건수: {len(pending) - resolved}건)")

    final = [v for v in items.values() if v["timestamp"] >= cutoff_ts]
    final.sort(key=lambda x: -x["timestamp"])
    final = final[:MAX_ITEMS]
    for v in final:
        v["id"] = make_id(norm_key(v["title"]))

    with open(NEWS_JSON, "w", encoding="utf-8") as f:
        f.write("[\n" + ",\n".join(json.dumps(v, ensure_ascii=False) for v in final) + "\n]\n")

    by_day = {}
    by_src = {}
    for v in final:
        d = datetime.fromtimestamp(v["timestamp"], KST).strftime("%m-%d")
        by_day[d] = by_day.get(d, 0) + 1
        by_src[v["source"]] = by_src.get(v["source"], 0) + 1
    unknown = sum(1 for v in final if v["lat"] is None)
    print(f"=== 완료: 저장 {len(final)}건 (이번 신규 {new_count}건) / RSS 성공 {ok_feeds} 실패 {fail_feeds} ===")
    print("날짜별:", dict(sorted(by_day.items())))
    print("언론사 상위:", dict(sorted(by_src.items(), key=lambda x: -x[1])[:15]))
    print(f"위치 미상: {unknown}건")


if __name__ == "__main__":
    main()
